      "conceptExpansion": [
        "Core idea: The development of microscopy allowed scientists to observe cells. Robert Hooke used the term cell after observing compartments in cork. Later observations by Leeuwenhoek and the work of Schleiden, Schwann and Virchow helped establish the modern cell theory: organisms are composed of cells, the cell is the basic unit of life, and new cells arise from pre-existing cells.",
        "Structure-function link: In this topic, the structure of the relevant cell component must always be connected to what it does. A strong answer explains not only what the structure is, but why its structure makes its function possible.",
        "Exam reasoning: If a question changes the situation, first identify the structure involved, then state its normal function, then predict the consequence of changing or removing that structure.",
        "Misconception check: A diagram is not a substitute for explanation. Learn the labels, but also learn the function and the relationship between the labelled parts."
      ],
      "definitions": [
        {
          "term": "cell theory",
          "definition": "The principle that all living organisms are made of cells, the cell is the basic unit of life, and new cells arise from pre-existing cells."
        },
        {
          "term": "Robert Hooke",
          "definition": "The scientist who observed thin slices of cork in 1665 and introduced the term cell after seeing box-like compartments."
        },
        {
          "term": "Anton van Leeuwenhoek",
          "definition": "The scientist who first observed and described living microscopic organisms using improved microscopes."
        },
        {
          "term": "Schleiden",
          "definition": "A botanist who concluded that plants are composed of cells."
        },
        {
          "term": "Schwann",
          "definition": "A zoologist who concluded that animals are composed of cells and helped establish cell theory."
        },
        {
          "term": "Virchow",
          "definition": "The scientist who stated that new cells arise from pre-existing cells."
        }
      ],
      "keyPoints": [
        "Discovery and Cell Theory is part of the logical organisation of cells.",
        "Structure and function are closely related.",
        "Use precise biological vocabulary in written answers.",
        "Compare similar structures by function, location and special features."
      ],
