      "id": "topic-6",
      "title": "Nucleus",
      "type": "concept",
      "explanation": "The nucleus is a membrane-bound organelle containing genetic material in a eukaryotic cell. It regulates many cellular activities and plays a central role in inheritance and cell division. Chromatin contains DNA associated with proteins; during cell division it becomes more condensed.",
      "conceptExpansion": [
        "Core idea: The nucleus is a membrane-bound organelle containing genetic material in a eukaryotic cell. It regulates many cellular activities and plays a central role in inheritance and cell division. Chromatin contains DNA associated with proteins; during cell division it becomes more condensed.",
        "Structure-function link: In this topic, the structure of the relevant cell component must always be connected to what it does. A strong answer explains not only what the structure is, but why its structure makes its function possible.",
        "Exam reasoning: If a question changes the situation, first identify the structure involved, then state its normal function, then predict the consequence of changing or removing that structure.",
        "Misconception check: A diagram is not a substitute for explanation. Learn the labels, but also learn the function and the relationship between the labelled parts."
      ],
      "definitions": [
        {
          "term": "nucleus",
          "definition": "A membrane-bound organelle containing most of the cell's genetic material and controlling many cellular activities."
        },
        {
          "term": "nuclear membrane",
          "definition": "The double membrane surrounding the nucleus that separates nuclear contents from the cytoplasm and contains nuclear pores."
        },
        {
          "term": "chromatin",
          "definition": "The material made mainly of DNA and associated proteins that forms chromosomes when condensed during cell division."
        },
        {
          "term": "DNA",
          "definition": "Deoxyribonucleic acid, the molecule that stores hereditary genetic information in cells."
        },
        {
          "term": "nucleolus",
          "definition": "A dense region inside the nucleus where components of ribosomes are produced and assembled."
        }
      ],
