      "id": "topic-8",
      "title": "Plastids and Chloroplasts",
      "type": "concept",
      "explanation": "Plastids occur in plant cells. Chloroplasts contain chlorophyll and are the main sites of photosynthesis. Their internal membrane system forms stacks called grana embedded in the stroma. Other plastids, such as chromoplasts and leucoplasts, have different functions.",
      "conceptExpansion": [
        "Core idea: Plastids occur in plant cells. Chloroplasts contain chlorophyll and are the main sites of photosynthesis. Their internal membrane system forms stacks called grana embedded in the stroma. Other plastids, such as chromoplasts and leucoplasts, have different functions.",
        "Structure-function link: In this topic, the structure of the relevant cell component must always be connected to what it does. A strong answer explains not only what the structure is, but why its structure makes its function possible.",
        "Exam reasoning: If a question changes the situation, first identify the structure involved, then state its normal function, then predict the consequence of changing or removing that structure.",
        "Misconception check: A diagram is not a substitute for explanation. Learn the labels, but also learn the function and the relationship between the labelled parts."
      ],
      "definitions": [
        {
          "term": "plastid",
          "definition": "A membrane-bound organelle found mainly in plant cells and algae; plastids include chloroplasts, chromoplasts and leucoplasts."
        },
        {
          "term": "chloroplast",
          "definition": "A green plastid containing chlorophyll where photosynthesis takes place in plant cells."
        },
        {
          "term": "chlorophyll",
          "definition": "The green pigment in chloroplasts that absorbs light energy for photosynthesis."
        },
        {
          "term": "grana",
          "definition": "Stacks of thylakoid membranes inside chloroplasts where the light-dependent reactions of photosynthesis occur."
        },
        {
          "term": "stroma",
          "definition": "The fluid-filled region of a chloroplast surrounding the grana, where the carbon-fixation reactions of photosynthesis occur."
        }
      ],
