      "explanation": "Prokaryotic cells lack a membrane-bound nucleus and generally have simpler internal organisation; bacteria are examples. Eukaryotic cells possess a membrane-bound nucleus and membrane-bound organelles. Both types have a plasma membrane, cytoplasm, ribosomes and genetic material.",
