      "title": "Plant Cell and Animal Cell",
      "type": "concept",
      "explanation": "Plant and animal cells share many basic structures, but plant cells typically have a cell wall, plastids and a large central vacuole. Animal cells lack a cell wall and chloroplasts. The comparison must be made carefully because not every plant cell looks identical and not every animal cell contains the same set of specialised structures.",
      "conceptExpansion": [
        "Core idea: Plant and animal cells share many basic structures, but plant cells typically have a cell wall, plastids and a large central vacuole. Animal cells lack a cell wall and chloroplasts. The comparison must be made carefully because not every plant cell looks identical and not every animal cell contains the same set of specialised structures.",
        "Structure-function link: In this topic, the structure of the relevant cell component must always be connected to what it does. A strong answer explains not only what the structure is, but why its structure makes its function possible.",
        "Exam reasoning: If a question changes the situation, first identify the structure involved, then state its normal function, then predict the consequence of changing or removing that structure.",
        "Misconception check: A diagram is not a substitute for explanation. Learn the labels, but also learn the function and the relationship between the labelled parts."
      ],
      "definitions": [
        {
          "term": "plant cell",
          "definition": "A eukaryotic cell typically containing a cellulose cell wall, plastids and a large central vacuole in addition to the basic cell structures."
        },
        {
          "term": "animal cell",
          "definition": "A eukaryotic cell lacking a cellulose cell wall and chloroplasts; it has a plasma membrane, cytoplasm, nucleus and other organelles."
        },
        {
          "term": "cell wall",
          "definition": "A rigid, non-living outer layer outside the plasma membrane of plant cells that provides support, protection and shape."
        },
        {
          "term": "chloroplast",
          "definition": "A green plastid containing chlorophyll where photosynthesis takes place in plant cells."
        },
        {
          "term": "vacuole",
          "definition": "A membrane-bound storage compartment; plant cells usually have a large central vacuole containing cell sap."
        }
      ],
